"""Three original theory papers: fourteen A questions and four paired B questions."""
from prediction_content import item as Q, number as N, choose

def paper(r):
    out=[]
    def add(label, cases): out.append((label, choose(r,cases)))
    add('1',[
      N('静電気','真空中で距離0.30mを隔てた点電荷+2μCと+3μCの間に働く力の大きさは何Nか。クーロン定数を9.0×10⁹N·m²/C²とする。',.6,[.06,.2,1.8,6],'N','F=kQ₁Q₂/r²=9.0×10⁹×2×10⁻⁶×3×10⁻⁶/0.30²=0.60N。同符号なので力は反発力である。'),
      N('静電気','極板面積と誘電率を変えずに平行板コンデンサの極板間隔を3倍にした。変更前の静電容量が12μFのとき、変更後の静電容量は何μFか。',4,[3,6,12,36],'μF','C=εS/dなので極板間隔に反比例する。12/3=4μF。接続する電源の有無は静電容量の幾何学的な値には影響しない。'),
      N('静電気','静電容量3μFと6μFのコンデンサを直列に接続し、全体に90Vを加えた。3μFのコンデンサに加わる電圧は何Vか。',60,[15,30,45,90],'V','直列では電荷が等しい。合成容量2μF、電荷180μCなので、3μF側の電圧は180/3=60V。容量の小さい側の電圧が高くなる。')])
    add('2',[
      N('磁気','インダクタンス0.20Hの理想コイルに5.0Aの直流電流が流れている。蓄えられる磁気エネルギーは何Jか。',2.5,[.5,1,5,10],'J','W=LI²/2=0.20×5.0²/2=2.5J。LIは磁束鎖交数でありエネルギーではない。'),
      N('磁気','巻数200のコイルを貫く1巻き当たりの磁束が、0.010sの間に一様に2.0mWb減少した。誘導起電力の大きさは何Vか。',40,[.04,.4,4,400],'V','誘導起電力の大きさはN|ΔΦ/Δt|。200×2.0×10⁻³/0.010=40V。磁束の減少を妨げる向きに起電力が生じる。'),
      N('磁気','同じ方向に電流が流れる、十分に長い2本の平行導線がある。一方の電流を2倍、導線間距離を半分にし、他方の電流を変えなかった。単位長さ当たりの電磁力は元の何倍か。',4,[.5,1,2,8],'倍','単位長さ当たりの力はμI₁I₂/(2πd)。電流の2倍と距離の逆数の2倍が掛かるので4倍となる。同方向の電流間の力は引力。')])
    add('3',[
      N('直流回路','長さ100m、断面積2.0mm²の導線の抵抗は何Ωか。抵抗率を0.020Ω·mm²/mとし、温度変化を無視する。',1,[.01,.1,2,4],'Ω','R=ρl/S=0.020×100/2.0=1.0Ω。抵抗率と断面積の単位を対応させれば、mm²をm²へ変換する必要はない。'),
      N('直流回路','20℃で10.0Ωの抵抗体がある。20℃を基準とする抵抗温度係数を0.0040/Kとすると、70℃での抵抗は何Ωか。温度に対し直線的に変化するものとする。',12,[8,10.2,14,30],'Ω','R₇₀=R₂₀{1+α₂₀(70−20)}=10×(1+0.004×50)=12Ω。温度差は50Kである。'),
      N('直流回路','同じ材質の円形断面導線で、長さを元の2倍、直径を元の2倍にした。温度が等しいとき、抵抗は元の何倍か。',.5,[.25,1,2,4],'倍','断面積は直径の2乗に比例して4倍、長さは2倍。R=ρl/Sより抵抗比は2/4=0.5倍となる。')])
    add('4',[
      N('直流回路','12Vの理想電圧源に、6Ωと3Ωを並列に接続した負荷をつないだ。電源から流れ出る全電流は何Aか。',6,[2,3,4,9],'A','各枝電流は12/6=2Aと12/3=4A。キルヒホッフの電流則から全電流は6Aとなる。'),
      N('直流回路','ブリッジ回路の左枝は上側2Ω・下側4Ω、右枝は上側3Ω・下側Rxの直列である。両枝の上下端に同じ電源を接続し、左右の中点間の電流が0となった。Rxは何Ωか。',6,[1.5,2,3,12],'Ω','平衡条件は2/4=3/Rx。交差積を等しくすると2Rx=12、Rx=6Ω。中点間に電位差がない条件である。'),
      N('直流回路','開放電圧24V、内部抵抗4Ωの電源に、抵抗RLを接続する。RLで消費する電力が最大となるときのRLは何Ωか。',4,[0,2,8,24],'Ω','純抵抗の直流回路では、負荷抵抗を電源の内部抵抗と等しくすると最大電力が得られる。P=24²RL/(4+RL)²の最大点はRL=4Ω。')])
    add('5',[
      N('直流回路','起電力1.5V、内部抵抗0.10Ωの同じ電池を4個直列につなぎ、外部抵抗2.6Ωを接続した。電流は何Aか。',2,[.5,1.5,2.5,6],'A','合成起電力は6V、内部抵抗は0.40Ω。全抵抗3.0ΩなのでI=6/3=2A。'),
      N('直流回路','100Ωの抵抗に直流200Vを加えて10分間通電した。消費電力量は何kWhか。',.0667,[.00667,.4,.667,4],'kWh','P=V²/R=400W=0.4kW。10分は1/6時間なので、電力量は0.4/6≒0.0667kWh。'),
      N('直流回路','内部抵抗1Ωの電源に4Ωの負荷をつないだとき、負荷電流は3Aだった。起電力は何Vか。',15,[3,9,12,20],'V','起電力は負荷端子電圧と内部電圧降下の和。E=I(R+r)=3×(4+1)=15V。')])
    add('6',[
      N('交流回路','正弦波電圧v(t)=100√2 sin(100πt)Vの周波数は何Hzか。',50,[25,100,157,314],'Hz','角周波数ω=100πrad/s。f=ω/(2π)=50Hz。100√2Vは最大値で、実効値は100V。'),
      N('交流回路','正弦波交流電圧の最大値が200Vである。実効値として最も近いものはどれか。',141,[63.7,100,200,283],'V','正弦波の実効値は最大値/√2。200/√2≒141.4V。平均値や半周期平均値と区別する。'),
      Q('交流回路','同じ周波数の電圧v=Vₘsinωtと電流i=Iₘsin(ωt−π/3)がある。電流の位相について正しい記述はどれか。','電圧に対して60°遅れる。',['電圧に対して30°遅れる。','電圧に対して60°進む。','電圧に対して120°進む。','電圧と同相である。'],'電流の位相は電圧よりπ/3小さいので、電流は60°遅れる。負の位相差を進みと取り違えない。')])
    add('7',[
      N('交流回路','抵抗6Ωと誘導性リアクタンス8Ωを直列につないだ負荷に、実効値100Vを加えた。電流実効値は何Aか。',10,[7.14,12.5,16.7,20],'A','直列RL回路のインピーダンスの大きさは√(6²+8²)=10Ω。I=100/10=10A。'),
      N('交流回路','抵抗8Ωと容量性リアクタンス6Ωを直列につないだ負荷の力率はいくらか。',.8,[.2,.4,.6,1],'','|Z|=√(8²+6²)=10Ω。力率cosφ=R/|Z|=0.8で、電流は電圧より進む。'),
      N('交流回路','インダクタンス0.10Hと静電容量100μFを直列につないだ理想回路の共振周波数に最も近いものはどれか。',50.3,[5.03,15.9,159,503],'Hz','共振条件はωL=1/(ωC)。f₀=1/(2π√LC)=1/(2π√(0.1×100×10⁻⁶))≒50.3Hz。')])
    add('8',[
      N('交流回路','単相負荷の電圧200V、電流10A、力率0.60のとき、有効電力は何kWか。すべて実効値とする。',1.2,[.8,1.6,2,3.33],'kW','単相の有効電力P=VIcosφ=200×10×0.60=1200W=1.2kW。'),
      N('交流回路','有効電力3kW、遅れ無効電力4kvarの単相負荷の皮相電力は何kVAか。',5,[1,3,4,7],'kVA','複素電力の大きさS=√(P²+Q²)=√(3²+4²)=5kVA。力率は3/5=0.60。'),
      N('交流回路','有効電力6kWの負荷で、力率が0.60から1.0へ改善された。電圧を一定とすると、改善後の電流は改善前の何倍か。',.6,[.36,.8,1,1.67],'倍','有効電力と電圧が一定ならI=P/(Vcosφ)。電流比は改善前の力率/改善後の力率=0.60/1.0=0.60。')])
    add('9',[
      N('交流回路','対称三相のY結線負荷で、相電圧実効値が100Vである。線間電圧実効値として最も近いものはどれか。',173,[57.7,100,200,300],'V','Y結線の線間電圧は相電圧の√3倍。100√3≒173.2V。'),
      N('交流回路','対称三相のΔ結線負荷で、各相の電流実効値が10Aである。線電流実効値として最も近いものはどれか。',17.3,[5.77,10,20,30],'A','Δ結線の線電流は相電流の√3倍。10√3≒17.3A。'),
      N('交流回路','線間電圧200V、線電流5A、力率1の三相平衡負荷の有効電力として最も近いものはどれか。',1732,[577,1000,2000,3000],'W','三相有効電力は√3VLILcosφ。√3×200×5≒1732W。単相のVIと区別する。')])
    add('10',[
      N('過渡現象','抵抗20kΩとコンデンサ100μFの直列回路の時定数は何sか。',2,[.002,.2,20,2000],'s','RC回路の時定数τ=RC=20000×100×10⁻⁶=2s。'),
      N('過渡現象','抵抗4Ωとコイル0.80Hを直列接続したRL回路の時定数は何sか。',.2,[.05,.8,3.2,5],'s','RL回路の時定数τ=L/R=0.80/4=0.20s。RC回路のRCと混同しない。'),
      N('過渡現象','十分に充電されたコンデンサを抵抗を通じて放電する。時定数の1倍の時間が経過したとき、端子電圧は初期電圧の約何倍か。',.368,[0,.135,.5,.632],'倍','放電電圧v=V₀e^(−t/τ)。t=τではe⁻¹≒0.368倍。充電時の立ち上がり割合0.632とは異なる。')])
    add('11',[
      Q('電子回路','pn接合ダイオードに順方向電圧を加えたときの一般的な状態として正しいものはどれか。','空乏層が狭まり、電流が流れやすくなる。',['空乏層が広がり、必ず完全な絶縁体になる。','pn接合が永久に消滅する。','逆方向にのみ大電流が流れる。','温度に関係なく常に抵抗値が一定になる。'],'順方向の外部電圧は接合の障壁を低くし、空乏層を狭める。電流電圧特性は非線形であり、単純な一定抵抗ではない。'),
      Q('電子回路','MOSFETのゲートに関する説明として最も適切なものはどれか。','ゲートは絶縁膜を介してチャネルを電界で制御する。',['ゲート電流だけで機械的な接点を開閉する。','正常動作でもゲート絶縁膜を常に破壊して使う。','ゲートは必ずソースに短絡して使う。','ゲートはコレクタとも呼ばれる。'],'MOSFETは金属・酸化膜・半導体構造をもち、ゲート電圧による電界でチャネルを制御する。入力抵抗は高いが、過渡的な容量充放電電流は流れる。'),
      N('電子回路','エミッタ接地回路で、直流ベース電流が40μA、直流電流増幅率hFEが100である。能動領域でのコレクタ電流は何mAか。',4,[.04,.4,40,400],'mA','IC=hFE IB=100×40μA=4000μA=4mA。能動領域での関係であり、飽和時へ無条件には適用しない。')])
    add('12',[
      N('電子回路','理想演算増幅器の反転増幅回路で、入力抵抗10kΩ、帰還抵抗50kΩ、入力電圧0.20Vである。非反転入力を接地し、出力飽和を起こさないとき、出力電圧は何Vか。',-1,[-.04,.04,1,5],'V','反転増幅度は−Rf/Rin=−5。出力は−5×0.20=−1.0V。負帰還が成立し、電源電圧の範囲内であるという条件を使う。'),
      N('電子回路','理想演算増幅器の非反転増幅回路で、反転入力と接地間の抵抗が10kΩ、出力から反転入力への帰還抵抗が30kΩである。電圧増幅度はいくらか。',4,[.25,1,3,-3],'','非反転増幅度は1+Rf/Rg=1+30/10=4。反転増幅回路の−Rf/Rinとは異なる。'),
      Q('電子回路','増幅器に適切な負帰還をかけたときの一般的な効果として正しいものはどれか。','閉ループ利得は下がるが、利得の安定性が高まる。',['必ず発振し、信号増幅ができなくなる。','利得とひずみが必ず同じ比率で増える。','入力信号がなくても無限大の電力を出力する。','電源からの電力供給が不要になる。'],'負帰還は出力の一部を入力から差し引く。一般に利得を抑える代わりに、素子ばらつきの影響やひずみを小さくできる。安定性には周波数特性の設計も必要。')])
    add('13',[
      N('電気計測','内部抵抗1kΩ、最大目盛10Vの直流電圧計を、最大目盛100Vとして使いたい。直列に追加する倍率器の抵抗は何kΩか。',9,[.1,1,10,99],'kΩ','最大目盛電流は10/1000=0.01A。100Vに必要な全抵抗は10kΩなので、追加分は10−1=9kΩ。'),
      N('電気計測','内部抵抗1Ω、最大目盛1Aの直流電流計を10Aレンジに拡張する。並列に接続する分流器の抵抗として最も近いものはどれか。',.111,[.01,.1,1,9],'Ω','電流計に1A、分流器に9Aを流す。両者の電圧1Vは等しいので、分流器抵抗は1/9≒0.111Ω。'),
      Q('電気計測','交流用変流器（CT）の一次側に電流が流れている。二次側の電流計を取り外すときの注意として適切なものはどれか。','二次回路を開放しないよう、定められた短絡手順をとる。',['二次側を開放しておけば電圧は必ず0Vになる。','一次電流が流れていても二次回路を自由に開放できる。','二次側にコンデンサを直列に入れれば必ず安全になる。','二次巻線の端子間を大きな抵抗だけで接続する。'],'通電中のCT二次側を開放すると鉄心磁束が増加し、高電圧発生や過熱の危険がある。実作業では設備ごとの保安手順に従って短絡などを行う。')])
    add('14',[
      N('磁気','正弦波磁束をもつ変圧器で、周波数50Hz、巻数100、最大磁束2.0mWbである。巻線の誘導起電力実効値は何Vか。',44.4,[4.44,22.2,88.8,444],'V','正弦波ではE=4.44fNΦm。4.44×50×100×0.002=44.4V。磁束の最大値を用いる。'),
      N('磁気','空隙を無視できる一様な環状磁路で、磁路長0.50m、コイル巻数200、電流0.50Aである。磁界の強さは何A/mか。',200,[20,50,100,400],'A/m','アンペアの周回積分則からHl=NI。H=200×0.50/0.50=200A/m。'),
      N('磁気','磁束密度0.50Tの一様磁界に、長さ0.40mの直線導体を磁界と直角に置き、3.0Aを流した。導体に働く力の大きさは何Nか。',.6,[.06,.2,1.2,6],'N','電磁力F=BIl sinθ。θ=90°なのでF=0.50×3.0×0.40=0.60N。')])

    # B15: independent, fully stated source/load cases, two linked fields each.
    e,ri,rl=choose(r,[(24,2,10),(36,3,9),(48,4,8)])
    i=e/(ri+rl); v=i*rl
    common=f'起電力{e}V、内部抵抗{ri}Ωの直流電源に、{rl}Ωの負荷を接続した。'
    out += [('15a',N('直流回路',common+'(a) 負荷電流は何Aか。',i,[i/2,i*2,i*3,i*4],'A',f'内部抵抗を含む全抵抗は{ri+rl}Ω。I=E/(ri+RL)={e}/{ri+rl}={i:g}A。')),
            ('15b',N('直流回路',common+'(b) 負荷だけで消費される電力は何Wか。',i*i*rl,[i*i*ri,e*i,i*i*rl/4,i*i*rl*3],'W',f'負荷電力はI²RL={i:g}²×{rl}={i*i*rl:g}W。電源全体の発生電力EIや内部損失I²riと区別する。'))]
    # B16: parallel resistor and ideal inductor, capacitive compensation.
    voltage,resistance,xl=choose(r,[(120,30,40),(200,50,40),(100,25,20)])
    p=voltage**2/resistance; reactive=voltage**2/xl
    common=f'実効値{voltage}Vの正弦波電源に、抵抗{resistance}Ωと誘導性リアクタンス{xl}Ωの理想コイルを並列に接続した。'
    out += [('16a',N('交流回路',common+'(a) 回路全体の有効電力は何Wか。',p,[p/2,p*2,reactive,reactive*2],'W',f'理想コイルの平均有効電力は0。抵抗だけが有効電力を消費し、P=V²/R={voltage}²/{resistance}={p:g}W。')),
            ('16b',N('交流回路',common+'(b) この負荷にコンデンサを並列接続し、合成力率を1にしたい。必要な進み無効電力の大きさは何varか。',reactive,[reactive/2,reactive*2,p,p*2],'var',f'コイルの遅れ無効電力Q=V²/XL={voltage}²/{xl}={reactive:g}var。同じ大きさの進み無効電力を加えると打ち消せる。'))]
    # B17: selectable electromagnetic induction application.
    turns,freq,flux=choose(r,[(200,50,.004),(100,60,.005),(300,50,.002)])
    emf=4.44*turns*freq*flux
    common=f'巻数{turns}、周波数{freq}Hzのコイルを貫く磁束が正弦波状に変化し、最大磁束は{flux*1000:g}mWbである。'
    out += [('17a',N('磁気',common+'(a) 誘導起電力実効値は何Vか。',emf,[emf/2,emf*2,emf/4,emf*4],'V',f'正弦波ではE=4.44fNΦm。代入すると{emf:g}V。')),
            ('17b',N('磁気',common+'(b) 同じ誘導起電力実効値を保ったまま周波数を2倍にした。最大磁束は何mWbになるか。',flux*500,[flux*250,flux*1000,flux*2000,flux*4000],'mWb',f'巻数一定でΦm=E/(4.44fN)。電圧が同じで周波数が2倍なら磁束は半分の{flux*500:g}mWb。'))]
    # B18: selectable electronic-circuit case; limits are explicit.
    rin,rf,vin=choose(r,[(10,40,.5),(20,60,.4),(10,20,.75)])
    gain=-rf/rin; vout=gain*vin
    common=f'理想演算増幅器の反転増幅回路で、入力抵抗{rin}kΩ、帰還抵抗{rf}kΩ、非反転入力は接地されている。電源は±12Vとし、出力飽和を起こさない。'
    out += [('18a',N('電子回路',common+'(a) 電圧増幅度はいくらか。',gain,[-gain,1-gain,1/gain,-1/gain],'',f'負帰還が成立する反転増幅回路ではAv=−Rf/Rin=−{rf}/{rin}={gain:g}。')),
            ('18b',N('電子回路',common+f'(b) 入力を{vin:g}Vとしたときの出力電圧は何Vか。',vout,[-vout,vout/2,-vout/2,0],'V',f'出力はVo=−(Rf/Rin)Vi={gain:g}×{vin:g}={vout:g}V。±12Vの範囲内なので、設定した非飽和条件を満たす。'))]
    return out
